NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Romans'

CHAPTERS = {
    1: {
        1: 'Pavel, služabnik Jezusa Kristusa, poklican, da bi bil apostol, odbran za evangelij Boga,',
        2: '(ki ga je vnaprej obljubil po svojih prerokih v svetih pismih),',
        3: 'glede svojega Sina Jezusa Kristusa, našega Gospoda, ki je glede na meso zrasel iz Davidovega potomca;',
        4: 'in z vstajenjem od mrtvih je, glede na duha svetosti, razglasil, da je Božji Sin z močjo;',
        5: 'po katerem smo zaradi njegovega imena prejeli milost in apostolstvo, za poslušnost veri med vsemi narodi;',
        6: 'med katere ste po Jezusu Kristusu poklicani tudi vi.',
        7: 'Vsem, ki ste v Rimu, Božji ljubljenci, poklicani, da ste sveti: ›Milost vam in mir od Boga, našega Očeta in Gospoda Jezusa Kristusa.‹',
        8: 'Najprej se po Jezusu Kristusu zahvaljujem svojemu Bogu za vas vse, da se o vaši veri govori po vsem celotnem svetu.',
        9: 'Kajti Bog je moja priča, ki mu služim s svojim duhom v evangeliju njegovega Sina, da vas brez prenehanja vedno omenjam v svojih molitvah,',
        10: '§ ker prosim, če bi na kakršenkoli način torej končno lahko imel uspešno potovanje, da po Božji volji pridem k vam.',
        11: 'Kajti hrepenim, da vas vidim, da bi vam lahko posredoval kak duhoven dar, z namenom, da boste lahko utrjeni;',
        12: 'to je, da bom lahko skupaj z vami potolažen po vzajemni veri, tako vaši kakor moji.',
        13: 'Torej, nočem, da bi bili nepoučeni, bratje, da sem se pogosto namenil priti k vam (toda doslej sem bil zadržan), da bi lahko imel, kakor med drugimi pogani, nekaj sadu tudi med vami.',
        14: 'Dolžnik sem, tako Grkom kakor barbarom, tako modrim, kakor ne modrim.',
        15: 'Torej, kar se mene tiče, sem pripravljen evangelij oznaniti tudi vam, ki ste v Rimu.',
        16: 'Kajti ne sramujem se Kristusovega evangelija, kajti ta je Božja moč za rešitev duš vsakemu, ki veruje; najprej Judu in tudi Grku.',
        17: 'Kajti v njem se razodeva Božja pravičnost, iz vere v vero, kakor je pisano: ›Pravični bo živel iz vere.‹',
        18: '§ Kajti Božji bes je razodet iz nebes zoper vso brezbožnost in nepravičnost ljudi, ki resnico zadržujejo v nepravičnosti;',
        19: 'zato ker je to, kar je lahko spoznano od Boga, očitno v njih; kajti Bog jim je to pokazal.',
        20: 'Kajti od stvarjenja sveta so nevidne stvari o njem jasno vidne, ker so razumljene po stvareh, ki so narejene; celó njegova večna moč in Božanstvo, tako da so brez opravičila.',
        21: 'Zato ker ko so spoznali Boga, ga niso slavili kakor Boga niti niso bili hvaležni, temveč so v svojih zamislih postali prazni in njihovo nespametno srce je otemnelo.',
        22: 'Ker so o sebi izpovedovali, da so modri, so postali bedaki',
        23: 'in slavo netrohljivega Boga spremenili v podobo, podobno trohljivemu človeku in pticam in štirinožnim živalim in plazečim stvarem.',
        24: 'Zato jih je tudi Bog, zaradi poželenj njihovih lastnih src, prepustil nečistosti, da med seboj onečaščajo svoja lastna telesa.',
        25: '§ Ki so Božjo resnico zamenjali v laž in so bolj oboževali in služili stvarstvu kakor Stvarniku, ki je blagoslovljen na veke. Amen.',
        26: 'Zaradi tega razloga jih je Bog prepustil ogabnim strastem; kajti celó njihove ženske so spremenile naravno uporabo v to, kar je protinaravno.',
        27: 'In prav tako so tudi moški, ki so opustili naravno uporabo ženske, v svojem poželenju goreli eden k drugemu; moški so z moškimi počenjali to, kar je nespodobno in na sebi prejemali to povračilo svoje zablode, ki je bilo primerno.',
        28: 'In celó kot v svojem spoznanju niso želeli obdržati Boga, jih je Bog izročil pokvarjenemu umu, da počenjajo te stvari, ki niso primerne.',
        29: '§ Izpolnjeni so z vso nepravičnostjo, prešuštvom, zlobnostjo, pohlepnostjo, zlonamernostjo; polni zavisti, umora, razpravljanja, prevar, pogubnosti; opravljivci,',
        30: 'obrekovalci, sovražniki Boga, kruti, ponosni, bahači, izmišljevalci hudobnih stvari, neposlušni staršem,',
        31: '§ brez razumevanja, lomilci zavez, brez naravne naklonjenosti, nespravljivi, neusmiljeni.',
        32: 'Ki poznajo Božje sodbe, da so tisti, ki zagrešijo takšne stvari, vredni smrti, ne samo, da to počenjajo, temveč imajo zadovoljstvo v tistih, ki jih počno.',
    },
    2: {
        1: 'Torej si neopravičljiv, oh človek, kdorkoli si, ki sodiš; kajti v čemer sodiš drugega, obsojaš sebe; kajti ti, ki sodiš, počneš iste stvari.',
        2: 'Toda mi smo prepričani, da je Božja sodba, glede na resnico, zoper te, ki izvajajo takšne stvari.',
        3: 'In mar misliš ti, oh človek, ki sodiš tiste, ki takšne stvari počno in delaš isto, da boš ubežal Božji sodbi?',
        4: 'Ali preziraš bogastva njegove dobrote in prizanašanja in potrpežljivosti, ne vedoč, da te Božja dobrota vodi h kesanju?',
        5: 'Toda po svojem brezčutnem in zakrknjenem srcu si nabiraš bes za dan besa in razodetja pravične Božje sodbe;',
        6: 'ki bo vsakemu človeku povrnil glede na njegova dejanja.',
        7: 'Večno življenje tem, ki si s potrpežljivim vztrajanjem v dobrem ravnanju prizadevajo za slavo in čast in nesmrtnost;',
        8: 'toda tistim, ki so prepirljivi in ne ubogajo resnice, temveč ubogajo nepravičnost, ogorčenost in bes.',
        9: 'Stiska in tesnoba nad vsako dušo človeka, ki počne zlo, najprej judovsko in prav tako pogansko;',
        10: 'toda slava, čast in mir vsakemu človeku, ki dela dobro, najprej Judu in tudi poganu,',
        11: 'kajti pri Bogu ni oziranja na osebe.',
        12: 'Kajti kolikor jih je grešilo brez postave, bodo tudi propadli brez postave; in kolikor jih je grešilo v postavi, bodo sojeni po postavi.',
        13: '(Kajti pred Bogom niso pravični poslušalci postave, temveč bodo opravičeni uresničevalci postave.',
        14: 'Kajti kadar pogani, ki nimajo postave, po naravi delajo stvari, ki so vsebovane v postavi, so tisti, ki nimajo postave, samim sebi postava;',
        15: 'ki kažejo delo postave, zapisano v njihovih srcih in tudi njihova vest pričuje in njihove misli se medtem obtožujejo ali pa opravičujejo druga drugo),',
        16: 'na dan, ko bo Bog po Jezusu Kristusu sodil skrivnosti ljudi, glede na moj evangelij.',
        17: 'Glej, imenuješ se Jud in počivaš na postavi in se bahaš z Bogom',
        18: 'in poznaš njegovo voljo in ker si poučen iz postave, odobravaš stvari, ki so odličnejše;',
        19: 'in si prepričan, da si ti sam vodnik slepim, svetloba tem, ki so v temi,',
        20: 'inštruktor nespametnih, učitelj otročičev, ki imaš v postavi obrazec spoznanja in resnice.',
        21: 'Ti torej, ki poučuješ drugega, samega sebe [pa] ne poučiš? Ti, ki oznanjaš naj človek ne krade, [pa] kradeš?',
        22: 'Ti, ki praviš, naj človek ne stori zakonolomstva, [pa] storiš zakonolomstvo? Ti, ki preziraš malike, [pa] storiš svetoskrunstvo?',
        23: 'Ti, ki se bahaš s postavo, [pa] zaradi prelamljanja postave onečaščaš Boga?',
        24: 'Kajti zaradi vas se med pogani izreka bogokletje proti Božjemu imenu, kakor je pisano.',
        25: 'Kajti obreza resnično koristi, če se držiš postave; toda če si lomilec postave, je tvoja obreza postala neobreza.',
        26: 'Torej, če se neobrezani drži pravičnosti postave, mar ne bo njegova neobreza šteta za obrezo?',
        27: 'In ali ne bo neobrezani, ki je po naravi, če izpolnjuje postavo, sodil tebe, ki po črki in obrezi prestopaš postavo?',
        28: 'Kajti ni Jud tisti, ki je tak na zunaj; niti ni obreza ta, ki je zunanja, v mesu;',
        29: 'toda Jud je tisti, ki je tak navznoter; in obreza je ta od srca, v duhu in ne po črki; katerega hvala ni od ljudi, temveč od Boga.',
    },
    3: {
        1: 'Kakšno prednost ima potem Jud? Ali kakšna korist je od obreze?',
        2: 'Velika, [v] vsakem pogledu, predvsem, ker so bili Božji izreki zaupani njim.',
        3: '§ Kajti kaj, če nekateri niso verovali? Mar bo njihova nevera naredila Božjo vero brez učinka?',
        4: 'Bog ne daj; da, naj bo Bog resničen, toda vsak človek lažnivec, kakor je pisano: ›Da boš lahko opravičen po svojih besedah in lahko zmagaš, kadar si sojen.‹',
        5: 'Toda če naša nepravičnost razkriva Božjo pravičnost, kaj bomo rekli? Ali je Bog, ki se maščuje, nepravičen? (Govorim kakor človek),',
        6: 'Bog ne daj; kajti kako bo potem Bog sodil svet?',
        7: 'Kajti če je Božja resnica zaradi moje laži v njegovo slavo bolj obilna; zakaj sem tudi jaz še vedno sojen kakor grešnik?',
        8: 'In ne raje (kot smo obrekljivo prikazani in kot nekateri zatrjujejo, da pravimo): ›Delajmo zlo, da lahko pride dobro?‹ katerih obsodba je pravična.',
        9: 'Kaj torej? Ali smo mi boljši kakor oni? Ne, nikakor ne, kajti prej smo tako Judom kakor poganom dokazali, da so vsi pod grehom;',
        10: 'kakor je pisano: ›Nobenega pravičnega ni, ne, niti enega ni.',
        11: 'Nobenega ni, ki razume, nobenega ni, ki išče Boga.',
        12: 'Vsi so odšli proč s poti, skupaj so postali nekoristni; nobenega ni, ki dela dobro, ne, niti enega ni.',
        13: 'Njihovo grlo je odprt mavzolej; s svojimi jeziki so uporabljali prevaro; strup kober je pod njihovimi ustnicami;',
        14: 'katerih usta so polna preklinjanja in grenkobe;',
        15: 'njihova stopala so hitra, da prelijejo kri;',
        16: 'uničenje in beda sta na njihovih poteh;',
        17: 'in poti miru niso spoznali;',
        18: 'pred njihovimi očmi ni strahu Božjega.‹',
        19: 'Torej mi vemo, da katerekoli besede govori postava, govori tistim, ki so pod postavo, da se vsaka usta lahko zamaše in ves svet lahko postane kriv pred Bogom.',
        20: 'Torej po dejanjih postave v njegovem pogledu ne bo opravičeno nobeno meso, kajti spoznanje greha je po postavi.',
        21: 'Toda sedaj je jasno pokazana Božja pravičnost brez postave, ker je izpričana po postavi in prerokih;',
        22: 'celó Božja pravičnost, ki je po veri Jezusa Kristusa vsem in nad vsemi temi, ki verujejo; kajti nobene razlike ni,',
        23: 'kajti vsi so grešili in niso dosegli Božje slave;',
        24: 'opravičeni pa so zastonj, po njegovi milosti prek odkupitve, ki je v Kristusu Jezusu;',
        25: 'ki ga je Bog postavil, da postane spravna daritev po veri v njegovo kri, da po Božji prizanesljivosti oznani svojo pravičnost za odpuščanje grehov, ki so minuli;',
        26: 'da oznani, pravim, ob tem času svojo pravičnost; da je lahko sam pravičen in opravičevalec tistega, ki veruje v Jezusa.',
        27: 'Kje je torej bahanje? Izključeno je. Po kakšni postavi? Po delih? Ne, temveč po postavi vere.',
        28: 'Torej sklenemo, da je človek opravičen po veri, brez del postave.',
        29: 'Ali je on samo Bog Judov? Ali ne tudi poganov? Da, tudi poganov.',
        30: 'Ker je resnično en Bog, ki bo obrezo opravičil po veri in neobrezo preko vere.',
        31: 'Ali mi potem preko vere postavo razveljavljamo? Bog ne daj; da, mi utrjujemo postavo.',
    },
    4: {
        1: 'Kaj bomo torej rekli, da je našel Abraham, naš oče, kar se nanaša na meso?',
        2: 'Kajti če bi bil Abraham opravičen po delih, bi se imel s čim ponašati; toda ne pred Bogom.',
        3: 'Kajti kaj pravi pismo? Abraham je verjel Bogu in to mu je bilo šteto za pravičnost.',
        4: 'Torej tistemu, ki dela, nagrada ni šteta po milosti, temveč po dolgu.',
        5: 'Toda tistemu, ki ne dela, temveč veruje v tistega, ki opravičuje brezbožnega, je njegova vera šteta za pravičnost.',
        6: 'Celo kakor tudi David opisuje blaženost človeka, ki mu Bog pripisuje pravičnost brez del,',
        7: 'rekoč: ›Blagoslovljeni so tisti, katerih krivičnosti so odpuščene in katerih grehi so pokriti.',
        8: 'Blagoslovljen je človek, ki mu Gospod ne bo pripisal greha.‹',
        9: 'Prihaja potem ta blaženost samo na obrezo ali tudi na neobrezo? Kajti pravimo, da je bila vera Abrahamu šteta za pravičnost.',
        10: 'Kako je bila potem šteta? Ko je bil v obrezi ali v neobrezi? Ne v obrezi, temveč [ko je bil] v neobrezi.',
        11: 'In ko je bil še neobrezan, je prejel znamenje obreze, pečat pravičnosti vere, ki jo je imel, da bi bil lahko oče vseh teh, ki verujejo, čeprav niso obrezani, da bi bila lahko tudi njim pripisana pravičnost;',
        12: 'in oče obrezanih, teh, ki niso samo iz obreze, temveč ki tudi hodijo po stopinjah tiste vere našega očeta Abrahama, ki jo je imel, ko je bil še neobrezan.',
        13: '§ Kajti obljuba, da naj bi bil dedič sveta, ni bila [dana] Abrahamu ali njegovemu semenu preko postave, temveč preko pravičnosti iz vere.',
        14: 'Kajti če bodo dediči tisti, ki so iz postave, je vera ničeva in obljuba brez učinka;',
        15: 'zato ker postava povzroča bes; kajti kjer ni nobene postave, tam ni prestopka.',
        16: 'Torej je to iz vere, da bi bilo lahko po milosti; z namenom, da bi bila obljuba lahko zanesljiva vsemu semenu; ne samo temu, ki je iz postave, temveč tudi temu, ki je iz Abrahamove vere, ki je oče nas vseh,',
        17: '(kakor je pisano: ›Naredil sem te za očeta mnogih narodov‹) pred njim, ki mu je veroval, celó [pred] Bogom, ki oživlja mrtve in kliče te stvari, ki niso, kakor da bi bile.',
        18: 'Ki je proti upanju veroval v upanje, da bi lahko postal oče mnogih narodov; glede na to, kar je bilo spregovorjeno: ›Takšno bo tvoje seme.‹',
        19: 'In ker ni bil slaboten v veri, ko je bil star okoli sto let, svojega lastnega telesa torej ni imel za mrtvega niti ne še omrtvelost Sarine maternice.',
        20: 'Ob Božji obljubi ni okleval zaradi nevere, temveč je bil močan v veri in dal slavo Bogu;',
        21: 'in je bil popolnoma prepričan, da kar je on obljubil, je zmožen tudi izpolniti.',
        22: 'Zato mu je bilo to šteto za pravičnost.',
        23: 'Torej, da mu je bilo šteto, to ni bilo napisano samo zaradi njega,',
        24: '§ temveč tudi zaradi nas, ki nam bo šteto, če verujemo v tistega, ki je obudil našega Gospoda Jezusa od mrtvih;',
        25: 'ki je bil izročen zaradi naših prestopkov in je bil ponovno obujen zaradi našega opravičenja.',
    },
    5: {
        1: 'Torej, ker smo opravičeni iz vere, imamo po našem Gospodu Jezusu Kristusu z Bogom mir.',
        2: 'Po njem imamo tudi po veri dostop v to milost, v kateri stojimo in se veselimo v upanju Božje slave.',
        3: 'In ne samo to, temveč se ponašamo tudi s stiskami, ker vemo, da stiska dela potrpežljivost,',
        4: 'in potrpežljivost preizkušenost, in preizkušenost upanje;',
        5: 'upanje pa ne sramotí, ker je Božja ljubezen prelita v naša srca po Svetem Duhu, ki nam je dan.',
        6: 'Kajti ko smo bili še brez moči, je Kristus ob primernem času umrl za brezbožne.',
        7: 'Kajti komaj bi nekdo umrl za pravičnega človeka, čeprav bi si morda nekdo celó upal umreti za dobrega človeka.',
        8: 'Toda Bog izkazuje svojo ljubezen do nas v tem, da je Kristus umrl za nas, medtem ko smo bili še grešniki.',
        9: 'Toliko bolj bomo potem po njem rešeni pred besom, ker smo sedaj opravičeni po njegovi krvi.',
        10: 'Kajti če smo bili s smrtjo njegovega Sina pobotani k Bogu, ko smo bili sovražniki, bomo toliko bolj, ker smo pobotani, po njegovem življenju rešeni.',
        11: 'In ne samo tako, temveč se tudi veselimo v Bogu po svojem Gospodu Jezusu Kristusu, po katerem smo sedaj prejeli spravo.',
        12: 'Zatorej, kakor je po enem človeku na svet vstopil greh in po grehu smrt; in je tako smrt prešla na vse ljudi, ker so vsi grešili;',
        13: '(kajti do postave je bil na svetu greh, toda greh ni pripisan v času, ko ni postave.',
        14: 'Vendar je od Adama do Mojzesa kraljevala smrt, celó nad temi, ki niso grešili po podobnosti Adamovega prestopka, ki je podoba tega, ki je imel priti.',
        15: 'Toda z zastonjskim darom ni tako kakor s pregreho. Kajti če so po prestopku enega mnogi mrtvi, sta toliko bolj Božja milost in darilo po milosti, ki je po enem človeku, Jezusu Kristusu, mnoge obogatila.',
        16: 'In z darom ni tako kakor je bilo s tistim, ki je grešil. Kajti sodba je bila po enem v obsodbo, toda zastonjski dar je od mnogih prestopkov k opravičenju.',
        17: 'Kajti če je po prestopku enega človeka zakraljevala smrt, bodo toliko bolj tisti, ki prejemajo obilje milosti in od daru pravičnosti, v življenju kraljevali po enem, Jezusu Kristusu.)',
        18: 'Torej kakor je prišla po prestopku enega sodba nad vse ljudi v obsodbo, točno tako je prišel po pravičnosti enega zastonjski dar nad vse ljudi v opravičenje življenja.',
        19: 'Kajti kakor so po neposlušnosti enega človeka mnogi postali grešniki, tako bodo po poslušnosti enega mnogi postali pravični.',
        20: 'Poleg tega je postava vstopila, da bi bil prestopek lahko obilen. Toda kjer je greh obilen, je milost storila veliko več obilja,',
        21: 'da kakor je greh kraljeval za smrt, točno tako lahko milost kraljuje po pravičnosti za večno življenje po Jezusu Kristusu, našem Gospodu.',
    },
    6: {
        1: 'Kaj bomo potem rekli? Ali bomo nadaljevali v grehu, da bo milost lahko obilna?',
        2: 'Bog ne daj. Kako bomo mi, ki smo mrtvi grehu, še živeli v njem?',
        3: 'Ali ne veste, da tako mnogi izmed nas, ki smo bili krščeni v Jezusa Kristusa, smo bili krščeni v njegovo smrt?',
        4: 'Torej smo s krstom z njim pokopani v smrt, da naj bi podobno kakor je bil Kristus obujen od mrtvih po Očetovi slavi, točno tako tudi mi hodili v novosti življenja.',
        5: 'Kajti če smo bili skupaj posajeni v podobnost njegove smrti, bomo tudi v podobnost njegovega vstajenja,',
        6: 'ker vemo to, da je naš stari človek križan z njim, da bi bilo telo greha lahko uničeno, da naj odslej ne bi več služili grehu.',
        7: 'Kajti kdor je mrtev, je osvobojen pred grehom.',
        8: 'Torej, če smo s Kristusom mrtvi, verujemo, da bomo z njim tudi živeli,',
        9: 'vedoč, da Kristus, ko je bil obujen od mrtvih, nič več ne umira; nad njim smrt nima več gospostva.',
        10: '§ Kajti kdor je umrl, je enkrat umrl grehu, toda kdor živi, živi Bogu.',
        11: '§ Prav tako tudi sebe štejte za zares mrtve grehu, toda žive za Boga, po Jezusu Kristusu, našem Gospodu.',
        12: 'Ne dopustite, da torej greh kraljuje v vašem umrljivem telesu, da bi ga morali ubogati v njegovih poželenjih.',
        13: 'Niti ne dajajte svojih udov grehu, kot orodja krivičnosti, temveč dajte sebe Bogu, kakor tisti, ki so od mrtvih živi in svoje ude kot orodja pravičnosti Bogu.',
        14: 'Kajti greh nad vami ne bo imel gospostva; kajti niste pod postavo, temveč pod milostjo.',
        15: 'Kaj torej? Mar bomo grešili, ker nismo pod postavo, temveč pod milostjo? Bog ne daj.',
        16: 'Ali ne veste, da komur same sebe dajete [za] služabnike v pokorščino, ste njegovi služabniki, komur se pokoravate; bodisi grehu v smrt ali poslušnosti v pravičnost?',
        17: 'Toda hvala Bogu, da ste bili služabniki grehu, vendar ste iz srca ubogali to obliko nauka, ki vam je bil izročen.',
        18: 'Ko ste bili torej osvobojeni greha, ste postali služabniki pravičnosti.',
        19: 'Zaradi šibkosti vašega mesa govorim po običaju ljudi; kajti kakor ste svoje služabniške ude dali nečistosti in krivičnosti za krivičnost; točno tako dajte sedaj svoje služabniške ude pravičnosti za svetost.',
        20: '§ Kajti ko ste bili služabniki grehu, ste bili svobodni, [prosti] pred pravičnostjo.',
        21: 'Kakšen sad ste takrat imeli v tistih stvareh, ki se jih sedaj sramujete? Kajti konec tistih stvari je smrt.',
        22: 'Toda sedaj, ko ste osvobojeni greha in ste postali služabniki Bogu, imate svoj sad v svetost in konec večno življenje.',
        23: 'Kajti plačila za greh so smrt; toda Božji dar je večno življenje po Jezusu Kristusu, našem Gospodu.',
    },
    7: {
        1: 'Ali ne veste, bratje (kajti govorim tem, ki poznajo postavo), da ima postava gospostvo nad človekom, dokler on živi?',
        2: 'Kajti ženska, ki ima soproga, je po postavi vezana k svojemu soprogu, dokler ta živi; toda če soprog umre, je odvezana od postave svojega soproga.',
        3: 'Torej če bo poročena k drugemu moškemu, medtem ko njen soprog živi, bo zaradi tega imenovana zakonolomka; toda če je njen soprog mrtev, je osvobojena te postave, tako da ni zakonolomka, čeprav je poročena k drugemu moškemu.',
        4: 'Tako, moji bratje, ste tudi vi po Kristusovem telesu postali mrtvi postavi, da bi bili poročeni k drugemu, celó k njemu, ki je obujen od mrtvih, da naj bi obrodili sad za Boga.',
        5: 'Kajti ko smo bili v mesu, so v naših udih delovale spodbude grehov, ki so bili po postavi, da obrodijo sad za smrt.',
        6: 'Toda sedaj smo osvobojeni postave, da bi mrtvi [postavi], pod katero smo bili držani, služili v novosti duha, ne pa v starosti črke.',
        7: 'Kaj bomo torej rekli? Ali je postava greh? Bog ne daj. Ne, nisem spoznal greha, razen po postavi; kajti ne bi spoznal poželenja, razen če postava ne bi rekla: ›Ne boš požêlel.‹',
        8: 'Toda greh, ki [si] po zapovedi jemlje priložnost, je v meni oblikoval vse vrste poželjivosti. Kajti brez postave je bil greh mrtev.',
        9: 'Kajti nekoč sem bil živ brez postave; toda ko je prišla zapoved, je greh oživel, jaz pa sem umrl.',
        10: 'In zapoved, ki je bila odrejena za življenje, sem spoznal, da je za smrt.',
        11: 'Kajti greh, ki [si] jemlje priložnost po zapovedi, me je zavedel in me po njej usmrtil.',
        12: 'Torej je postava svéta in zapoved svéta in pravična ter dobra.',
        13: 'Mi je potem to, kar je dobro, storilo smrt? Bog ne daj. Toda greh, da bi se lahko pokazal greh, dela s tem, kar je dobro, v meni smrt; ta greh utegne postati prek zapovedi silno grešen.',
        14: 'Kajti vemo, da je postava duhovna, toda jaz sem mesen, prodan pod greh.',
        15: 'Kajti tega, kar delam, ne dopuščam; kajti kar bi želel, tega ne delam, temveč počenjam to, kar sovražim.',
        16: 'Če torej počenjam to, česar nočem, soglašam k postavi, da je ta dobra.',
        17: 'Torej potem nisem več jaz, ki to počnem, temveč greh, ki prebiva v meni.',
        18: 'Kajti vem, da v meni (to je, v mojem mesu) ne prebiva nobena dobra stvar; kajti hoteti je z menoj pri roki, toda ne najdem tega, kako izvesti to, kar je dobro.',
        19: 'Kajti dobrega, ki ga hočem, ne delam, temveč zlo, ki ga nočem, to počnem.',
        20: 'Torej če delam to, česar nočem, to nisem več jaz, ki to počnem, temveč greh, ki prebiva v meni.',
        21: 'Odkril sem torej postavo, da ko sem hotel delati dobro, je z menoj prisotno zlo.',
        22: 'Kajti po notranjem človeku se veselim v Božji postavi,',
        23: 'toda v svojih udih vidim drugo postavo, ki se bori proti postavi mojega uma in me prinaša v sužnost postavi greha, ki je v mojih udih.',
        24: 'Oh pomilovanja vreden človek sem! Kdo me bo osvobodil iz telesa te smrti?',
        25: 'Zahvaljujem se Bogu po Jezusu Kristusu, našem Gospodu. Tako potem z umom služim Božji postavi, toda z mesom postavi greha.',
    },
    8: {
        1: '§ Torej sedaj ni nobene obsodbe tem, ki so v Kristusu Jezusu, ki ne živijo po mesu, temveč po Duhu.',
        2: 'Kajti postava Duha življenja v Kristusu Jezusu me je osvobodila postave greha in smrti.',
        3: 'Kajti česar postava ni mogla storiti, ker je bila slabotna po mesu, je [storil] Bog, ki je poslal svojega lastnega Sina v podobnosti grešnega mesa in za greh [in] obsodil greh v mesu,',
        4: 'da bi se lahko dopolnila pravičnost postave v nas, ki ne živimo po mesu, temveč po Duhu.',
        5: 'Kajti tisti, ki so po mesu, razmišljajo mesene stvari; toda tisti, ki so po Duhu, stvari od Duha.',
        6: 'Kajti biti mesenega mišljenja je smrt; toda biti duhovnega mišljenja je življenje in mir.',
        7: 'Ker je meseno mišljenje sovraštvo zoper Boga; kajti to ni podrejeno Božji postavi niti zares ne more biti.',
        8: 'Zaradi tega tisti, ki so v mesu, ne morejo ugajati Bogu.',
        9: 'Toda vi niste v mesu, temveč v Duhu, če je tako, da v vas prebiva Božji Duh. Torej, če katerikoli človek nima Kristusovega Duha, ni njegov.',
        10: 'In če je Kristus v vas, je telo mrtvo zaradi greha; toda Duh je življenje zaradi pravičnosti.',
        11: 'Toda če v vas prebiva Duh tistega, ki je Jezusa obudil od mrtvih, bo tisti, ki je po svojem Duhu, ki prebiva v vas, obudil Kristusa od mrtvih, tudi oživil vaša umrljiva telesa.',
        12: 'Torej bratje, mi smo dolžniki, [vendar] ne mesu, da bi živeli po mesu.',
        13: 'Kajti če živite po mesu, boste umrli, toda če po Duhu morite dejanja telesa, boste živeli.',
        14: 'Kajti kolikor jih je vodeno po Božjem Duhu, so Božji sinovi.',
        15: 'Kajti niste ponovno prejeli duha suženjstva za strah, temveč ste prejeli Duha posvojitve, s katerim kličemo: »Aba, Oče.«',
        16: 'Sam Duh z našim duhom prinaša pričevanje, da smo Božji otroci.',
        17: 'In če smo otroci, potem smo dediči; Božji dediči in sodediči s Kristusom, če je tako, da z njim trpimo, da bomo lahko tudi skupaj proslavljeni.',
        18: 'Kajti menim, da trpljenja tega sedanjega časa niso vredna, da se primerjajo s slavo, ki se bo razodela v nas.',
        19: 'Kajti iskreno pričakovanje stvarstva pričakuje manifestacijo Božjih sinov.',
        20: 'Kajti stvarstvo je bilo podvrženo ničevosti, ne voljno, temveč zaradi njega, ki si je le-to podvrgel v upanju,',
        21: 'ker bo tudi stvarstvo samo rešeno iz suženjstva trohnenja v veličastno svobodo Božjih otrok.',
        22: 'Kajti vemo, da celotno stvarstvo do zdaj skupaj stoka in se muči v bolečini.',
        23: 'Pa ne samo oni, temveč tudi mi, ki imamo prve sadove Duha, celo mi sami v sebi stokamo in čakamo na posvojitev, to je, odkupitev našega telesa.',
        24: 'Kajti rešeni smo po upanju; toda upanje, ki je videno, ni upanje; kajti kar človek vidi, čemu potem še upa?',
        25: 'Toda če upamo na to, česar ne vidimo, potem to pričakujemo s potrpežljivostjo.',
        26: 'Prav tako tudi Duh pomaga našim slabotnostim; kajti ne vemo, za kaj naj bi molili, kot bi morali, toda sam Duh posreduje za nas s stoki, ki ne morejo biti izrečeni.',
        27: 'In tisti, ki preiskuje srca, ve, kakšno je mišljenje Duha, ker on posreduje za svete glede na Božjo voljo.',
        28: 'In mi vemo, da vse stvari skupaj delajo v dobro tem, ki ljubijo Boga, tem, ki so poklicani glede na njegov namen.',
        29: 'Kajti katere je vnaprej poznal, je prav tako vnaprej določil, da bodo skladni podobi njegovega Sina, da bi bil ta lahko prvorojenec med mnogimi brati.',
        30: 'Poleg tega, katere je vnaprej določil, jih je tudi poklical; in katere je poklical, te je tudi opravičil; in katere je opravičil, te je tudi proslavil.',
        31: 'Kaj bomo potem rekli k tem stvarem? Če je Bog za nas, kdo je lahko zoper nas?',
        32: 'On, ki ni prizanesel svojemu lastnemu sinu, temveč ga je izročil za nas vse, kako nam ne bo z njim velikodušno dal tudi vseh stvari?',
        33: 'Kdo bo karkoli položil k obtožbi Božjih izvoljencev? Bog je, ki opravičuje.',
        34: 'Kdo je, kdor obsoja? To je Kristus, ki je umrl, da, bolje rečeno, ki je bil obujen, ki je celó na Božji desnici, ki prav tako posreduje za nas.',
        35: 'Kdo nas bo ločil od Kristusove ljubezni? Nas bo tegoba ali nesreča ali preganjanje ali lakota ali nagota ali nevarnost ali meč?',
        36: 'Kakor je pisano: ›Kajti zaradi tebe smo ves dan pobijani, imajo nas kakor ovce za klanje.‹',
        37: '§ Ne, v vseh teh stvareh smo več kot zmagovalci po njem, ki nas je vzljubil.',
        38: 'Kajti prepričan sem, da nas niti smrt, niti življenje, niti angeli, niti kneževine, niti moči, niti sedanje stvari, niti stvari, ki pridejo,',
        39: 'niti višina, niti globina, niti katerokoli drugo ustvarjeno bitje ne bo zmožno ločiti od Božje ljubezni, ki je v Kristusu Jezusu, našem Gospodu.',
    },
    9: {
        1: 'Govorim resnico v Kristusu, ne lažem, prav tako mi moja vest pričuje v Svetem Duhu,',
        2: 'da imam v svojem srcu veliko potrtost in nenehno bridkost.',
        3: 'Kajti lahko bi si želel, da bi bil jaz sam preklet pred Kristusom za svoje brate, moje sorodnike glede na meso;',
        4: 'ki so Izraelci, ki jim pripada posvojitev in slava in zaveze in dajanje postave in bogoslužje in obljube;',
        5: 'katerih so očetje in iz katerih je, glede na meso, prišel Kristus, ki je čez vse, Bog, blagoslovljen na veke. Amen.',
        6: 'Ne, kakor da Božja beseda ne učinkuje. Kajti niso vsi Izraelci, ki so iz Izraela;',
        7: 'niti zato, ker so Abrahamovi potomci, niso vsi otroci, temveč: ›Po Izaku se bo imenovalo tvoje seme.‹',
        8: 'To se pravi: »Tisti, ki so meseni otroci, tisti niso Božji otroci, temveč so za potomstvo šteti otroci obljube.«',
        9: 'Kajti to je beseda obljube: ›Ob tem času bom prišel in Sara bo imela sina.‹',
        10: 'Pa ne samo to; temveč, ko je tudi Rebeka spočela po enem, celó po našem očetu Izaku',
        11: '(kajti otroka se še nista rodila niti nista naredila ničesar dobrega ali zlega, da lahko ostane Božji namen glede na izvolitev, ne iz del, temveč iz njega, ki kliče),',
        12: 'ji je bilo rečeno: ›Starejši bo služil mlajšemu.‹',
        13: 'Kakor je pisano: ›Jakoba sem ljubil, toda Ezava sem sovražil.‹',
        14: 'Kaj bomo torej rekli? Ali je pri Bogu nepravičnost? Bog ne daj.',
        15: 'Kajti Mojzesu je rekel: ›Usmilil se bom, kogar se hočem usmiliti in sočutje bom imel, do kogar hočem imeti sočutje.‹',
        16: 'Torej potem to ni od tistega, ki hoče niti od tistega, ki teče, temveč od Boga, ki izkazuje usmiljenje.',
        17: 'Kajti pismo pravi faraonu: ›Celo za ta isti namen sem te dvignil, da lahko na tebi pokažem svojo moč in da se bo moje ime lahko razglasilo po vsej celotni zemlji.‹',
        18: 'Torej se usmili, kogar se hoče usmiliti in kogar hoče, tega zakrkne.',
        19: 'Torej mi boš rekel: »Zakaj še najde krivdo? Kajti kdo se je uprl njegovi volji?«',
        20: 'Ne, vendar, oh človek, kdo si ti, ki nasprotuješ Bogu? Ali bo oblikovana stvar rekla tistemu, ki jo je ustvaril: »Zakaj si me naredil takšno?«',
        21: 'Mar nima lončar moči nad ilom, da iz iste grude naredi eno posodo v čast, drugo pa v nečast?',
        22: 'Kaj pa, če je Bog, voljan pokazati svoj bes in pokazati svojo moč, z veliko potrpežljivosti prenašal posode besa, primerne za uničenje,',
        23: 'in da bi lahko dal spoznati bogastva svoje slave na posodah usmiljenja, ki jih je vnaprej pripravil za slavo,',
        24: 'celó nas, ki nas je poklical, ne samo izmed Judov, temveč tudi izmed poganov?',
        25: 'Kakor tudi pravi v Ozeju: ›Ljudi, ki niso bili moji, bom imenoval moji ljudje; in njo, ki ni bila ljubljena, ljubljeno.‹',
        26: 'In zgodilo se bo, da na kraju, kjer jim je bilo rečeno: ›Vi niste moji ljudje,‹ tam bodo imenovani otroci živega Boga.',
        27: 'Tudi Izaija kliče glede Izraela: ›Četudi bo število Izraelovih otrok kakor morskega peska, bo rešen ostanek;‹',
        28: '§ kajti dokončal bo delo in ga nenadoma prekinil v pravičnosti; ker bo Gospod na zemlji hitro opravil svoje delo.',
        29: 'In kakor je prej rekel Izaija: ›Razen če nam Gospod nad vojskami ne bi pustil semena, bi bili kakor Sódoma in bi posnemali Gomóro.‹',
        30: 'Kaj bomo potem rekli? Da so se pogani, ki si niso prizadevali za pravičnost, dokopali do pravičnosti, celó pravičnosti, ki je iz vere.',
        31: 'Toda Izrael, ki si je prizadeval za postavo pravičnosti, se ni dokopal do postave pravičnosti.',
        32: 'Zakaj? Ker tega niso iskali po veri, temveč kakor bi bilo to po delih postave. Kajti spotaknili so se ob tisti kamen spotike,',
        33: 'kakor je pisano: ›Glej, na Sionu položim kamen spotike in skalo pohujšanja; in kdorkoli veruje vanj, ne bo osramočen.‹',
    },
    10: {
        1: 'Bratje, moja srčna želja in prošnja k Bogu za Izrael je, da bi bili oni lahko rešeni.',
        2: 'Kajti prinašam jim pričevanje, da imajo gorečnost za Boga, toda ne glede spoznanja.',
        3: 'Kajti ker so bili nevedni glede Božje pravičnosti in so nameravali vzpostaviti svojo lastno pravičnost, se niso podvrgli Božji pravičnosti.',
        4: 'Kajti Kristus je konec postave za pravičnost vsakemu, ki veruje.',
        5: 'Kajti Mojzes opisuje pravičnost, ki je iz postave: ›Da bi človek, ki dela te stvari, živel po njih.‹',
        6: 'Toda pravičnost, ki je iz vere, govori na ta način: »Ne reci v svojem srcu: ›Kdo se bo povzpel v nebo?‹ (to je, Kristusa privedel dol od zgoraj);',
        7: 'ali: ›Kdo se bo spustil v brezno?‹ (to je, da Kristusa ponovno privede gor od mrtvih).«',
        8: 'Toda kaj ta pravi? Beseda je blizu tebe, celó v tvojih ustih in v tvojem srcu; to je, beseda vere, ki jo oznanjamo;',
        9: 'da če boš s svojimi usti priznal Gospoda Jezusa in boš v svojem srcu veroval, da ga je Bog obudil od mrtvih, boš rešen.',
        10: 'Kajti s srcem človek veruje v pravičnost, z usti pa je narejeno priznanje v rešitev duše.',
        11: 'Kajti pismo pravi: ›Kdorkoli veruje vanj, ne bo osramočen.‹',
        12: 'Kajti ni razlike med Judom in Grkom, kajti isti Gospod nad vsemi je bogat do vseh, ki kličejo k njemu.',
        13: 'Kajti kdorkoli bo klical h Gospodovemu imenu, bo rešen.',
        14: 'Kako bodo torej klicali njega, v katerega niso verovali? In kako bodo verovali vanj, o katerem niso slišali? In kako bodo slišali brez oznanjevalca?',
        15: 'In kako bodo oznanjali, razen če niso poslani? Kakor je pisano: ›Kako krasna so stopala teh, ki oznanjajo evangelij miru in prinašajo vesele novice o dobrih stvareh!‹',
        16: 'Toda evangeliju niso bili vsi poslušni. Kajti Izaija pravi: ›Gospod, kdo je verjel našemu poročilu?‹',
        17: '§ Tako potem vera prihaja po poslušanju in poslušanje po Božji besedi.',
        18: 'Vendar pravim: »Mar niso slišali?« Da, resnično, njihov glas je šel po vsej zemlji in njihove besede do koncev sveta.',
        19: 'Toda pravim: »Mar Izrael ni spoznal?« Mojzes najprej pravi: ›Izzval te bom k ljubosumju s tistimi, ki niso ljudstvo in z nespametnim narodom te bom jezil.‹',
        20: 'Toda Izaija je zelo pogumen in pravi: ›Našli so me tisti, ki me niso iskali; razodet sem bil tem, ki po meni niso spraševali.‹',
        21: 'Toda Izraelu reče: ›Cel ljubi dan sem svoje roke iztegoval k neposlušnim in upornim ljudem.‹',
    },
    11: {
        1: 'Potem pravim: ›Mar je Bog zavrgel svoje ljudi?‹ Bog ne daj. Kajti tudi sam sem Izraelec, iz Abrahamovega semena, iz Benjaminovega rodu.',
        2: 'Bog svojih ljudi, ki jih je vnaprej poznal, ni zavrgel. Mar ne veste, kaj pravi pismo o Eliju? Kako je posredoval k Bogu zoper Izraela, rekoč:',
        3: '›Gospod, pobili so tvoje preroke in spodkopali tvoje oltarje; in jaz sam sem ostal in strežejo mi po življenju.‹',
        4: 'Toda kaj mu pravi Božji odgovor? ›Prihranil sem si sedem tisoč mož, ki niso upognili kolena k Báalovi podobi.‹',
        5: 'Celó tako je tudi v tem sedanjem času ostanek glede na milosten izbor.',
        6: '§ In če je po milosti, potem to ni več iz del, drugače milost ni več milost. Toda če je iz del, potem to ni več milost, drugače delo ni več delo.',
        7: 'Kaj torej? Izrael ni dosegel tega, za kar si je prizadeval, temveč so to dosegli izvoljeni, ostali pa so bili zaslepljeni',
        8: '(glede na to, kakor je pisano: ›Bog jim je dal duha omrtvelosti, oči, da ne bi videli, ušesa, da ne bi slišali‹) do današnjega dne.',
        9: 'In David pravi: ›Naj jim njihova miza postane zanka in past in kamen spotike in njihovo povračilo;',
        10: 'naj njihove oči postanejo zatemnjene, da ne bodo mogli videti in vedno upogni njihov hrbet.‹',
        11: 'Potem pravim: ›Ali so se spotaknili, da bi padli?‹ Bog ne daj; temveč je po njihovem padcu rešitev duš toliko bolj prišla k poganom, da jih draži do ljubosumja.',
        12: 'Če so torej njihov padec bogastva sveta in njihovo zmanjševanje bogastva poganov; koliko bolj njihova polnost?',
        13: 'Kajti govorim vam, poganom, v kolikor sem apostol poganom, poveličujem svojo službo,',
        14: 'če lahko na kakršenkoli način izzovem kosanje teh, ki so moje meso in lahko rešim nekatere izmed njih.',
        15: 'Kajti če je odvračanje teh pobotanje sveta, kaj bo sprejemanje teh, če ne življenje iz mrtvih?',
        16: 'Kajti če je prvi sad svét, je svéta tudi gruda; in če je korenina svéta, so tudi veje.',
        17: 'In če so bile nekatere izmed vej odlomljene in si bil ti, ki si divja oljka, vcepljen v sredo mednje in si z njimi udeležen korenine in mastnosti oljke,',
        18: 'se ne bahaj zoper veje. Toda če se bahaš, ne nosiš korenine ti, temveč korenina tebe.',
        19: 'Rekel boš torej: ›Veje so bile odlomljene, da sem bil jaz lahko vcepljen.‹',
        20: 'Pravilno, ker so bile odlomljene zaradi nevere, ti pa stojiš po veri. Ne bodi vzvišen, temveč se boj.',
        21: 'Kajti če Bog ni prizanesel naravnim vejam, pazi, sicer tudi tebi ne prizanese.',
        22: 'Glej torej Božjo dobroto in strogost; na teh, ki so padli, strogost; toda do tebe dobroto, če nadaljuješ v njegovi dobroti; sicer boš tudi ti odsekan.',
        23: 'In tudi oni bodo vcepljeni, če ne bodo nenehno ostajali v neveri, kajti Bog jih je zmožen ponovno vcepiti.',
        24: 'Kajti če si bil odsekan z oljke, ki je po naravi divja in si bil vcepljen nasprotno naravi, na dobro oljko; koliko mnogo bolj bodo tisti, ki so naravne veje, vcepljeni na svojo lastno oljko?',
        25: 'Kajti nočem bratje, da bi bili nevedni o tej skrivnosti, da ne bi bili modri v svojih lastnih domišljavostih; ta delna slepota se je zgodila Izraelu, dokler ne bo vstopila polnost poganov.',
        26: 'In tako bo rešen ves Izrael, kakor je pisano: ›S Siona bo izšel Osvoboditelj in brezbožnost bo odvrnil od Jakoba;',
        27: 'kajti to je moja zaveza njim, ko jim bom odvzel njihove grehe.‹',
        28: 'Kar zadeva evangelij, so zaradi vas sovražniki; toda kar se tiče izbire, so ljubljeni zaradi očetov.',
        29: 'Kajti darovi in Božja poklicanost so brez kesanja.',
        30: 'Kajti kakor v preteklih časih niste verjeli Bogu, ste sedaj po njihovi neveri vendarle dosegli usmiljenje.',
        31: 'Točno tako tudi ti sedaj niso verjeli, da po vašem usmiljenju tudi sami lahko dosežejo usmiljenje.',
        32: 'Kajti Bog jih je vse zaprl v nevero, da bi se lahko vseh usmilil.',
        33: 'Oh globina bogastev, tako Božje modrosti kakor Božjega spoznanja! Kako nedoumljive so njegove sodbe in njegove poti neodkrite!',
        34: 'Kajti kdo je spoznal Gospodovo mišljenje? Ali kdo je bil njegov svetovalec?',
        35: 'Ali kdo mu je prvi dal in mu bo to ponovno poplačano?',
        36: 'Kajti iz njega in preko njega in njemu so vse stvari; ki mu bodi slava na veke. Amen.',
    },
    12: {
        1: 'Po Božjih milostih vas torej rotim, bratje, da ponudite svoja telesa v živo žrtev, sveto, Bogu sprejemljivo, kar je vaše smiselno bogoslužje.',
        2: 'In ne bodite prilagojeni temu svetu, temveč bodite preobraženi s prenavljanjem svojega mišljenja, da boste lahko razločili, kaj je tista dobra, sprejemljiva in popolna Božja volja.',
        3: 'Kajti po meni dani milosti pravim vsakemu človeku, ki je med vami, naj ne misli o samem sebi višje, kakor bi moral misliti; temveč naj misli trezno, glede na to, kakor je Bog vsakemu človeku podelil mero vere.',
        4: 'Kajti kakor imamo v enem telesu mnogo udov in vsi udje nimajo iste službe,',
        5: 'tako smo mi, ki nas je mnogo, eno telo v Kristusu in vsakdo udje drug drugemu.',
        6: 'Ker imamo torej darove, ki se razlikujejo glede na milost, ki nam je dana, če prerokba, prerokujmo glede na mero vere;',
        7: 'če služenje, počakajmo na naše služenje; ali kdor poučuje, na poučevanje;',
        8: 'ali kdor spodbuja, na spodbudo; kdor daje, naj to dela s preprostostjo; kdor vlada, z marljivostjo; kdor izkazuje usmiljenje, z vedrostjo.',
        9: 'Naj bo ljubezen brez pretvarjanja. Sovražite to, kar je zlo; trdno se držite tega, kar je dobro.',
        10: 'Bodite drug drugemu prijazno naklonjeni z bratoljúbjem; v spoštovanju dajajte prednost drug drugemu;',
        11: 'ne leni v poslu, [temveč] goreči v duhu; služeč Gospodu;',
        12: 'veseleč se v upanju; potrpežljivi v stiski; neprenehoma [neprenehoma: gr. iskreno, vztrajno, marljivo] nadaljujte v molitvi;',
        13: 'razdeljujte nujnim potrebam svetih, predani gostoljubnosti.',
        14: 'Blagoslavljajte te, ki vas preganjajo, blagoslavljajte in ne preklinjajte.',
        15: 'Veselite se s temi, ki se veselijo in jokajte s temi, ki jokajo.',
        16: 'Drug do drugega bodite istega mišljenja. Ne mislite visokih stvari, temveč se ponižajte k ljudem nizkega stanu. V svojih lastnih domišljavostih ne bodite modri.',
        17: 'Nobenemu človeku ne poplačajte zla za zlo. Pred očmi vseh ljudi skrbite za poštene stvari.',
        18: 'Če je mogoče, kolikor je v vaši moči, živite miroljubno z vsemi ljudmi.',
        19: '§ Srčno ljubljeni, sami se ne maščujte, temveč raje dajte prostor besu, kajti pisano je: ›Moje je maščevanje, jaz bom povrnil, govori Gospod.‹',
        20: 'Torej če je tvoj sovražnik lačen, ga nahrani; če je žejen, mu daj piti, kajti s takšnim početjem boš kopičil ognjeno oglje na njegovo glavo.',
        21: 'Ne bodite premagani od zla, temveč zlo premagajte z dobrim.',
    },
    13: {
        1: '§ Naj bo vsaka duša podrejena višjim oblastem. Kajti ni oblasti, razen od Boga; oblasti, ki so, so odrejene od Boga.',
        2: 'Kdorkoli se torej upira oblasti, se upira Božji odredbi in tisti, ki se upirajo, bodo sebi prejeli obsodbo.',
        3: 'Kajti vladarji niso strahota dobrim delom, temveč zlim. Se torej ne boš bal oblasti? Delaj to, kar je dobro in imel boš pohvalo od nje;',
        4: 'kajti ona je Božja služabnica, tebi v dobro. Toda če počneš to, kar je zlo, se boj, ker meča ne nosi zaman; kajti Božja služabnica je, maščevalka, da izvrši bes nad tistim, ki počenja zlo.',
        5: 'Zatorej morate biti nujno podrejeni, ne samo zaradi besa, temveč tudi zaradi vesti.',
        6: 'Kajti zaradi tega razloga tudi plačujete davek, kajti oni so Božji služabniki, ki nenehno skrbijo prav za to stvar.',
        7: 'Povrnite torej vsem njihove dolgove: davek, komur gre davek, carino, komur carino, strah, komur strah, spoštovanje, komur spoštovanje.',
        8: 'Nobenemu človeku ničesar ne dolgujte, razen da ljubite drug drugega; kajti kdor ljubi drugega, je izpolnil postavo.',
        9: '§ Zaradi tega: ›Ne boš zagrešil zakonolomstva,‹ ›Ne boš ubil,‹ ›Ne boš kradel,‹ ›Ne boš pričal po krivem,‹ ›Ne boš požêlel;‹ in če obstaja katera druga zapoved, je le-ta na kratko obsežena v tej besedi, namreč: ›Ljubil boš svojega bližnjega kakor samega sebe.‹',
        10: 'Ljubezen svojemu bližnjemu ne dela škode; torej je ljubezen izpolnitev postave.',
        11: 'In ker poznamo čas, da je sedaj skrajni čas, da se prebudimo iz spanja, kajti sedaj je naša rešitev duš bližje, kakor ko smo [začeli] verovati.',
        12: 'Noč je davno minila, dan je blizu. Odvrzimo torej dela teme in si nadenimo bojno opremo svetlobe.',
        13: 'Živimo pošteno, kakor podnevi; ne v upornosti in pijanosti, ne v nespodobnosti in razuzdanosti, ne v prepiru in zavisti.',
        14: 'Temveč si nadenite Gospoda Jezusa Kristusa in ne delajte si preskrbe za meso, da [bi] izpolnili poželenja le-tega.',
    },
    14: {
        1: 'Tistega, ki je v veri slaboten, sprejmite, toda ne k dvomljivim pričkanjem.',
        2: 'Kajti nekdo veruje, da lahko jé vse stvari; drug, ki je šibek, jé zelišča.',
        3: 'Naj tisti, ki jé, ne prezira tistega, ki ne jé; in kdor ne jé, naj ne sodi tistega, ki jé; kajti Bog ga je sprejel.',
        4: 'Kdo si ti, da sodiš služabnika drugega moža? Svojemu lastnemu gospodarju stoji ali pade. Da, obdržan bo pokonci; kajti Bog ga je zmožen postaviti pokonci.',
        5: 'Nek človek čisla en dan nad drugim, drugi čisla vsak dan enako. Naj bo vsak v svojem lastnem mišljenju popolnoma prepričan.',
        6: '§ Kdor upošteva dan, ga upošteva za Gospoda; kdor pa dneva ne upošteva, ga ne upošteva Gospodu. Kdor jé, jé za Gospoda, kajti zahvale daje Bogu; kdor pa ne jé, ne jé Gospodu in zahvalo daje Bogu.',
        7: 'Kajti nihče izmed nas ne živi zase in noben človek ne umira zase.',
        8: 'Kajti če živimo, živimo za Gospoda; in če umremo, umremo za Gospoda. Če torej živimo ali umremo, smo Gospodovi.',
        9: '§ Kajti zato je Kristus tako umrl kakor vstal in oživel, da bi bil lahko Gospod tako mrtvih kakor živih.',
        10: '§ Toda zakaj sodiš svojega brata? Ali zakaj zasmehuješ svojega brata? Kajti vsi bomo stali pred Kristusovim sodnim stolom.',
        11: 'Kajti pisano je: ›Kakor jaz živim, govori Gospod, bo vsako koleno pokleknilo k meni in vsak jezik bo priznal Boga.‹',
        12: 'Tako bo potem vsak izmed nas Bogu dal obračun o sebi.',
        13: 'Torej ne sodimo več drug drugega, temveč raje sodimo to, da noben človek ne postavi kamna spotike ali priložnosti, da pade, na pot svojega brata.',
        14: 'Vem in po Gospodu Jezusu sem prepričan, da ni nič sámo po sebi nečisto; toda temu, ki mêni, da je karkoli nečisto, je to zanj nečisto.',
        15: 'Toda če je tvoj brat užaloščen s tvojo jedjo, torej ne živiš v ljubezni. S svojo jedjo ne uničuj tega, za kogar je Kristus umrl.',
        16: 'Naj se potem o vašem dobrem ne govori zlo,',
        17: 'kajti Božje kraljestvo ni hrana in pijača, temveč pravičnost in mir in radost v Svetem Duhu.',
        18: 'Kajti kdor v teh stvareh služi Kristusu, je sprejemljiv za Boga in potrjen od ljudi.',
        19: 'Prizadevajmo si torej za stvari, ki delajo za mir in za stvari, s katerimi lahko eden izgrajuje drugega.',
        20: 'Zaradi hrane ne uničuj Božjega dela. Vse stvari so zares čiste; toda zlo je za tistega človeka, ki jé s spotiko.',
        21: 'Dobro je ne jesti mesa niti piti vina niti katerekoli stvari, s čimer se tvoj brat spotika ali je užaljen ali je postal slaboten.',
        22: 'Imaš vero? Imej jo zase pred Bogom. Srečen je, kdor sebe ne obsoja v tej stvari, ki jo on dopušča.',
        23: 'Kdor pa dvomi, je obsojen če jé, ker ne jé iz vere; kajti karkoli ni iz vere, je greh.',
    },
    15: {
        1: 'Torej moramo mi, ki smo močni, prenašati slabotnosti šibkih, ne pa da ugajamo sebi.',
        2: 'Naj vsak izmed nas ugaja svojemu bližnjemu v njegovo dobro, za izgrajevanje.',
        3: 'Kajti celó Kristus ni ugajal sebi; temveč, kakor je pisano: ›Graje teh, ki so te grajali, so padle name.‹',
        4: 'Kajti katerekoli stvari so bile vnaprej napisane, so bile napisane za naše učenje, da bi lahko preko potrpežljivosti in tolažbe iz pisem imeli upanje.',
        5: 'Naj vam torej Bog potrpežljivosti in tolažbe zagotovi, da boste istih misli drug do drugega glede na Kristusa Jezusa;',
        6: 'da boste lahko z enim umom in enimi usti slavili Boga, celó Očeta našega Gospoda Jezusa Kristusa.',
        7: 'Zatorej sprejemajte drug drugega, kakor je tudi Kristus nas sprejel v Božjo slavo.',
        8: 'Torej pravim, da je bil Jezus Kristus služabnik obreze za Božjo resnico, da potrdi obljube, narejene očetom,',
        9: 'in da lahko pogani zaradi njegovega usmiljenja slavijo Boga; kakor je pisano: ›Zaradi tega razloga te bom priznal med pogani in prepeval tvojemu imenu.‹',
        10: 'In ponovno pravi: ›Veselite se, vi pogani, z njegovimi ljudmi.‹',
        11: 'In ponovno: ›Hvalíte Gospoda, vsi pogani; in povzdigujte ga vsi ljudje.‹',
        12: 'In ponovno Izaija pravi: ›Jesejeva korenina bo in tisti, ki se bo dvignil, da kraljuje nad pogani; vanj bodo zaupali pogani.‹',
        13: 'Torej Bog upanja naj vas napolni z velikim veseljem in mirom v verovanju, da boste, po môči Svetega Duha, obilni v upanju.',
        14: 'In tudi jaz sam sem prepričan o vas, moji bratje, da ste tudi vi polni dobrote, izpolnjeni z vsem spoznanjem, zmožni tudi drug drugega opominjati.',
        15: 'Vendar, bratje, zaradi milosti, ki mi je dana od Boga, sem vam napisal na nek način pogumneje, kakor da vas spomnim,',
        16: 'da naj bi bil jaz služabnik Jezusa Kristusa za pogane, ko služim Božjemu evangeliju, da bi bila daritev poganov, posvečena po Svetem Duhu, lahko sprejemljiva.',
        17: 'Torej imam nekaj, s čimer se lahko po Jezusu Kristusu ponašam v teh stvareh, ki se nanašajo na Boga.',
        18: 'Kajti ne bom si drznil govoriti o katerikoli izmed tistih stvari, ki jih Kristus ni naredil po meni, da bi naredil pogane poslušne v besedi in dejanju,',
        19: 'preko mogočnih znamenj in čudežev, po moči Božjega Duha; tako da sem od Jeruzalema in naokoli do Ilirika obširno oznanil Kristusov evangelij.',
        20: 'Da, tako sem si prizadeval, da ne oznanim evangelija, kjer je bil Kristus imenovan, da ne bi gradil na temelju drugega človeka,',
        21: 'temveč kakor je pisano: ›Katerim ni bilo govorjeno, bodo videli; in tisti, ki niso slišali, bodo razumeli.‹',
        22: 'Zaradi tega razloga sem bil tudi sam zelo oviran, da pridem k vam.',
        23: 'Toda sedaj, ko v teh krajih nimam več prostora in imam ta mnoga leta veliko željo, da pridem k vam;',
        24: 'kadarkoli se odpravim na svoje potovanje v Španijo, bom prišel k vam, kajti zaupam, da vas na svojem potovanju vidim in da bom na svoji poti tja priveden mimo vas, da bi bil najprej nekoliko izpolnjen z vašo druščino.',
        25: 'Toda sedaj grem v Jeruzalem, da služim svetim.',
        26: 'Kajti tem iz Makedonije in Ahaje je ugajalo, da zberejo nek prispevek za revne svete, ki so v Jeruzalemu.',
        27: 'To jih je resnično veselilo; in njihovi dolžniki so. Kajti če so pogani postali soudeleženi njihovih duhovnih stvari, je tudi njihova dolžnost, da jim služijo v mesenih stvareh.',
        28: 'Ko bom torej to opravil in jim zapečatil ta sad, bom mimo vas prišel v Španijo.',
        29: '§ In prepričan sem, ko pridem k vam, da bom prišel v polnosti blagoslova Kristusovega evangelija.',
        30: 'Sedaj vas rotim, bratje, zaradi Gospoda Jezusa Kristusa in zaradi ljubezni Duha, da se skupaj z menoj borite v svojih molitvah zame k Bogu;',
        31: 'da bom lahko rešen pred temi, ki v Judeji ne verujejo; in da bodo mojo službo, ki jo imam za Jeruzalem, sveti lahko sprejeli;',
        32: 'da bom lahko po Božji volji z veseljem prišel k vam in bom lahko skupaj z vami okrepčan.',
        33: 'Torej Bog miru bodi z vami vsemi. Amen.',
    },
    16: {
        1: 'Priporočam vam našo sestro Fojbo, ki je služabnica cerkve, ki je v Kenhrejah,',
        2: 'da jo sprejmete v Gospodu, kakor se spodobi svetim in da ji pomagate v kateremkoli opravilu vas potrebuje. Kajti bila je pomočnica mnogim in tudi meni.',
        3: 'Pozdravite Prisko in Ákvila, moja pomočnika v Kristusu Jezusu,',
        4: 'ki sta za moje življenje tvegala svoja lastna vratova; ki se jima ne zahvaljujem samo jaz, temveč tudi vse cerkve poganov.',
        5: 'Prav tako pozdravite cerkev, ki je v njuni hiši. Pozdrav mojemu srčno ljubljenemu Epájnetu, ki je prvenec Ahaje Kristusu.',
        6: 'Pozdravite Marijo, ki je trdo delala z mnogim trudom za nas.',
        7: 'Pozdrav Andróniki in Juniju, mojima sorodnikoma in mojima sojetnikoma, ki sta pomembna med apostoli, ki sta bila tudi pred menoj v Kristusu.',
        8: 'Pozdravite Ampliáta, mojega ljubljenega v Gospodu.',
        9: 'Pozdrav Urbanu, našemu pomočniku v Kristusu in Stahiju, mojemu ljubljenemu.',
        10: 'Pozdrav Apélu, potrjenemu v Kristusu. Pozdrav tem, ki so iz Aristóbulove družine.',
        11: 'Pozdrav Heródionu, mojemu sorodniku. Pozdravite te, ki so iz Narcísove družine, ki so v Gospodu.',
        12: 'Pozdrav Trífajni in Trifózi, ki se trudita v Gospodu. Pozdrav ljubljeni Pêrsidi, ki se je veliko trudila v Gospodu.',
        13: 'Pozdravite Rufa, izbranca v Gospodu in njegovo mater in mojo [mater].',
        14: 'Pozdrav Asínkritu, Flegonu, Hermesu, Patrobáju, Hermáju in bratom, ki so z njimi.',
        15: 'Pozdrav Filológu in Juliji, Neréju in njegovi sestri ter Olimpáju in vsem svetim, ki so z njimi.',
        16: 'Pozdravite drug drugega s svetim poljubom. Pozdravljajo vas Kristusove cerkve.',
        17: 'Torej, rotim vas, bratje, zapomnite si te, ki povzročajo nesoglasja in prestopke, nasprotne nauku, ki ste se ga naučili; in izogibajte se jih.',
        18: 'Kajti ti, ki so takšni, ne služijo našemu Gospodu Jezusu Kristusu, temveč svojemu lastnemu trebuhu; in z lepimi besedami ter vljudnimi govori zavajajo srca preprostih.',
        19: 'Kajti vaša poslušnost je šla naokoli k vsem ljudem. Zaradi vas sem torej vesel; toda kljub temu bi vas želel imeti modre do tega, kar je dobro in nepokvarjene glede zla.',
        20: 'In Bog miru bo v kratkem zmečkal Satana pod vašimi stopali. Milost našega Gospoda Jezusa Kristusa naj bo z vami. Amen.',
        21: 'Pozdravljajo vas Timótej, moj delovni družabnik in moji sorodniki Lukij in Jazon in Sozípater.',
        22: 'Jaz, Tertij, ki sem napisal to poslanico, vas pozdravljam v Gospodu.',
        23: 'Pozdravlja vas Gaj, gostitelj mene in celotne cerkve. Pozdravlja vas Erást, glavni upravitelj mesta in brat Kvart.',
        24: '§ Milost našega Gospoda Jezusa Kristusa naj bo z vami vsemi. Amen.',
        25: 'Torej njemu, ki je sposoben, da vas utrdi v skladu z mojim evangelijem in oznanjevanjem Jezusa Kristusa, glede na razodetje skrivnosti, ki je bila tajno čuvana od nastanka sveta,',
        26: 'toda sedaj je razodeta in po pismih prerokov, glede na zapoved večnega Boga, razglašena vsem narodom zaradi poslušnosti veri;',
        27: 'Bogu, edinemu modremu, bodi slava po Jezusu Kristusu na veke. Amen. [Napisano Rimljanom iz Korinta in poslano po služabnici Fojbi iz kenhrejske cerkve.]',
    },
}
